`timescale 1ns / 1ps
//------------------------------------------------------------------------------
// gate_sprite : 32 x 40 outline bitmaps of the AND / OR / XOR gate symbols (generated by
//   scripts/gen_sprite.py, do not edit by hand). bits[31-col] is the pixel at column col.
//   kind : 0 AND, 1 OR, 2 XOR.  lead_a / lead_b : first symbol column on the rows of the
//   two input wires (rows 8 and 32), so the input wires can be drawn up to the symbol.
//------------------------------------------------------------------------------
module gate_sprite (
    input  wire [1:0]  kind,
    input  wire [5:0]  row,
    output reg  [31:0] bits,
    output reg  [4:0]  lead_a,
    output reg  [4:0]  lead_b
);
    always @* begin
        bits = 32'd0;
        case (kind)
            2'd0: begin
                case (row)
                    6'd0: bits = 32'hFFFFF000;
                    6'd1: bits = 32'h80001C00;
                    6'd2: bits = 32'h80000700;
                    6'd3: bits = 32'h80000180;
                    6'd4: bits = 32'h800000C0;
                    6'd5: bits = 32'h80000060;
                    6'd6: bits = 32'h80000030;
                    6'd7: bits = 32'h80000018;
                    6'd8: bits = 32'h80000008;
                    6'd9: bits = 32'h8000000C;
