                    6'd11: bits = 32'h80000006;
                    6'd12: bits = 32'h80000002;
                    6'd13: bits = 32'h80000002;
                    6'd14: bits = 32'h80000002;
                    6'd15: bits = 32'h80000003;
                    6'd16: bits = 32'h80000001;
                    6'd17: bits = 32'h80000001;
                    6'd18: bits = 32'h80000001;
                    6'd19: bits = 32'h80000001;
                    6'd20: bits = 32'h80000001;
                    6'd21: bits = 32'h80000001;
                    6'd22: bits = 32'h80000001;
                    6'd23: bits = 32'h80000001;
                    6'd24: bits = 32'h80000003;
                    6'd25: bits = 32'h80000002;
                    6'd26: bits = 32'h80000002;
                    6'd27: bits = 32'h80000002;
                    6'd28: bits = 32'h80000006;
                    6'd29: bits = 32'h80000004;
                    6'd30: bits = 32'h8000000C;
                    6'd31: bits = 32'h80000008;
                    6'd32: bits = 32'h80000018;
                    6'd33: bits = 32'h80000030;
                    6'd34: bits = 32'h80000060;
                    6'd35: bits = 32'h800000C0;
                    6'd36: bits = 32'h80000180;
                    6'd37: bits = 32'h80000700;
                    6'd38: bits = 32'h80001C00;
                    6'd39: bits = 32'hFFFFF000;
                    default: bits = 32'd0;
                endcase
            end
            2'd1: begin
                case (row)
                    6'd0: bits = 32'hFF000000;
                    6'd1: bits = 32'h31F80000;
                    6'd2: bits = 32'h180F0000;
                    6'd3: bits = 32'h0C01E000;
                    6'd4: bits = 32'h04003800;
                    6'd5: bits = 32'h06000E00;
                    6'd6: bits = 32'h02000300;
                    6'd7: bits = 32'h02000180;
