                    6'd9: bits = 32'h01000030;
                    6'd10: bits = 32'h01000010;
                    6'd11: bits = 32'h01000008;
                    6'd12: bits = 32'h0100000C;
                    6'd13: bits = 32'h01800004;
                    6'd14: bits = 32'h00800002;
                    6'd15: bits = 32'h00800002;
                    6'd16: bits = 32'h00800003;
                    6'd17: bits = 32'h00800001;
                    6'd18: bits = 32'h00800001;
                    6'd19: bits = 32'h00800001;
                    6'd20: bits = 32'h00800001;
                    6'd21: bits = 32'h00800001;
