                    6'd32: bits = 32'h02000180;
                    6'd33: bits = 32'h02000300;
                    6'd34: bits = 32'h06000E00;
                    6'd35: bits = 32'h04003800;
                    6'd36: bits = 32'h0C01E000;
                    6'd37: bits = 32'h180F0000;
                    6'd38: bits = 32'h31F80000;
                    6'd39: bits = 32'hFF000000;
                    default: bits = 32'd0;
                endcase
            end
            2'd2: begin
                case (row)
                    6'd0: bits = 32'hEFE00000;
                    6'd1: bits = 32'h333E0000;
                    6'd2: bits = 32'h1983C000;
                    6'd3: bits = 32'h0CC07000;
                    6'd4: bits = 32'h04401C00;
                    6'd5: bits = 32'h06600700;
