                    6'd31: bits = 32'h03300060;
                    6'd32: bits = 32'h022000C0;
                    6'd33: bits = 32'h02200180;
                    6'd34: bits = 32'h06600700;
                    6'd35: bits = 32'h04401C00;
                    6'd36: bits = 32'h0CC07000;
                    6'd37: bits = 32'h1983C000;
                    6'd38: bits = 32'h333E0000;
                    6'd39: bits = 32'hEFE00000;
                    default: bits = 32'd0;
                endcase
            end
            default: bits = 32'd0;
        endcase
    end
    always @* begin
        case (kind)
            2'd0: begin lead_a = 5'd0; lead_b = 5'd0; end
            2'd1: begin lead_a = 5'd6; lead_b = 5'd6; end
            2'd2: begin lead_a = 5'd6; lead_b = 5'd6; end
            default: begin lead_a = 5'd0; lead_b = 5'd0; end
        endcase
    end
endmodule
